query SearchResults($query: String!, $channel: String) {
  products(filter: {search: $query}, channel: $channel, first: 20) {
    edges {
      node {
        id
        name
        slug
        thumbnail {
          url
          alt
        }
        thumbnail2x: thumbnail(size: 510) {
          url
        }
        category {
          id
          name
        }
      }
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      startCursor
    }
  }
}
